import { readFileSync } from "node:fs";
import path from "node:path";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test("uploading a document returns 201 with status processing and records an audit event", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a vendor in draft status owned by the member's tenant
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `billing.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = await created.json();
    expect(vendor.status).toBe("draft");

    // Act: upload the insurance certificate as a real file part
    const filePath = sample("insurance_certificate.txt");
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: path.basename(filePath),
          mimeType: "text/plain",
          buffer: readFileSync(filePath),
        },
      },
    });

    // Assert: response status and initial document status
    expect(upload.status(), await upload.text()).toBe(201);
    const document = await upload.json();
    expect(document.kind).toBe("insurance_certificate");
    expect(document.vendor_id).toBe(vendor.id);
    expect(document.status, JSON.stringify(document)).toBe("processing");

    // Assert: audit event is recorded (may be written asynchronously)
    await expect
      .poll(async () => {
        const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(audit.status(), await audit.text()).toBe(200);
        const body = (await audit.json()) as { items: { action: string }[] };
        return body.items.map((event) => event.action);
      }, { message: "document.uploaded audit event" })
      .toContain("document.uploaded");
  });
});
